CREATE DATABASE IF NOT EXISTS pc_configurator CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pc_configurator;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,role VARCHAR(255) NOT NULL DEFAULT 'user',remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX idx_user_role(role)) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,description TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE components (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,brand VARCHAR(255) NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,power_watts INT UNSIGNED NULL,socket VARCHAR(255) NULL,ram_type VARCHAR(255) NULL,form_factor VARCHAR(255) NULL,wattage INT UNSIGNED NULL,length_mm INT UNSIGNED NULL,max_gpu_length_mm INT UNSIGNED NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,CONSTRAINT fk_components_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,INDEX idx_components_category_price(category_id,price),INDEX idx_components_brand(brand),CONSTRAINT chk_price CHECK(price>0)) ENGINE=InnoDB;
CREATE TABLE configurations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,status VARCHAR(255) NOT NULL DEFAULT 'draft',total_price DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,CONSTRAINT fk_configurations_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_configurations_user_status(user_id,status)) ENGINE=InnoDB;
CREATE TABLE configuration_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,configuration_id BIGINT UNSIGNED NOT NULL,component_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,CONSTRAINT fk_items_configuration FOREIGN KEY(configuration_id) REFERENCES configurations(id) ON DELETE CASCADE,CONSTRAINT fk_items_component FOREIGN KEY(component_id) REFERENCES components(id) ON DELETE RESTRICT,UNIQUE KEY uq_configuration_component(configuration_id,component_id),CONSTRAINT chk_quantity CHECK(quantity>=1)) ENGINE=InnoDB;
CREATE TABLE compatibility_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE,description TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
